scwin.grid1_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
    return false;
    //				return true;
}
scwin.grid2_ongroupby = function(options) {
    options.rowNumHeader = {
        inputType: 'expression',
        expression: 'toggle() + depthStr() + "    [ " + count() + " 건 ]  "',
        align: 'left',
        colSpan: 5
    };
    options.rowNumFooter = {
        colSpan: 3
    };
    options.rowStatusFooter = {
        value: '합계'
    };
    options.groupbyFooter = [{
        inputType: 'expression',
        expression: 'SUM("col3")'
    }];
    this.groupby(options);
}
scwin.selectbox1_onviewchange = function(info) {
    var data = eval("scwin.data" + info.newValue);
    dataList1.setData(data.slice(0));
}
scwin.trigger1_onclick = function() {
    var row = dataList1.getTotalRow();
    for (var i = 0; i < row; i++) {
        console.log(i + " ::::: " + dataList1.getCellData(i, 'col3'));
    }
};
scwin.grid1_groupbyFilterBoxFormatter = function(f) {
    console.log(JSON.stringify(f));
}
scwin.grid1_oncellclick = function(row, col) {
    var rrowIdx = dataList1.getRealRowIndex(row);
    console.log('gridview getFocusedRowIndex');
    console.log(grid1.getFocusedRowIndex());
    console.log('getCellData >> focusedRowIndex : ' + dataList1.getCellData(grid1.getFocusedRowIndex(), col));
    console.log('getRowJSON >> focusedRowIndex : ');
    console.log(dataList1.getRowJSON(grid1.getFocusedRowIndex()));
}
scwin.formatter = function(data) {
    console.log(data);
};
scwin.trigger2_onclick = function(e) {};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#grid1_header4', 'drag-n-drop', {
        dx: -10,
        dy: -50
    });
}
scwin.moveScroll = function() {
    for (var i = 0; i < 30; i++) {
        scwin.simulateWrapper("#grid1_groupbyZone_list", "key-combo", {
            combo: "down-arrow"
        });
    }
}
scwin.checkVal = function() {
    return parseInt(WebSquare.wUnit.getJq('#grid1_customFilter_scrollView').css('height')) < 35;
}
scwin.checkVal2 = function() {
    return WebSquare.wUnit.getJq($('.w2grid_groupbyZone_list_listColumn_text').last()).text() == '9';
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플실행 후 '금액'항목의 필터리스트를 클릭하고 마우스 스크롤로 이동하여 맨아래까지 값이 보여지는지 확인한다.(아래로 이동할수 있는 역삼각형모양 클릭으로도 확인 가능)
    //1. After running the sample, click on the filter list in the 'Amount' item and move the mouse scroll to see the value to the bottom. (You can also check by clicking the inverted triangle shape to move down)
    //Verify step 1. The scroll is moved to the bottom and works normally (Previously, the scroll could not be moved to the bottom and the value could not be seen)
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('grid1_header4_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. '금액'항목을 groupby시키고 필터리스트를 클릭하고 마우스 스크롤로 이동하여 맨아래까지 값이 보여지는지 확인한다.
    //2. Group the 'Amount' item, click on the filter list, and scroll to the bottom of the list to see the value.
    //Verify step 2. The scroll is moved to the bottom and works normally (Previously, the scroll was not moved to the bottom, so the value could not be seen)
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.moveScroll()");
    WebSquare.wUnit.addCommand("pause", "100");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //formatter
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 29-Mar-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
